function inView(it){
  if(view==="archive") return it.archived;
  if(view==="later")   return it.later && !it.archived;
  return !it.archived; // all
}
function matches(it, q){
  if(!inView(it)) return false;
  if(activeTag && !it.tags.includes(activeTag)) return false;
  if(!q) return true;
  const hay=(it.title+" "+it.note+" "+it.url+" "+it.tags.join(" ")).toLowerCase();
  return hay.includes(q);
}
const VIEW_LABEL = {all:"Saved", later:"Read later", archive:"Archive"};
const EMPTY_MSG = {
  all:"No bookmarks yet — paste a link above to save your first one.",
  later:"Nothing in your read-later list. Mark a bookmark “Read later” to add it.",
  archive:"Your archive is empty. Archive a bookmark to keep it here without cluttering the main list."
};

function renderNav(){
  document.querySelectorAll(".navbtn").forEach(b=>{
    b.classList.toggle("active", b.dataset.view===view);
  });
}

function renderItems(){
  const el=$("items");
  const q=($("search").value||"").trim().toLowerCase();
  const shown = items.filter(it=>matches(it,q));
  $("listHeading").textContent = (q||activeTag) ? "Results ("+shown.length+")" : VIEW_LABEL[view];
  if(shown.length===0){
    el.innerHTML = (q||activeTag)
      ? '<div class="empty">No bookmarks match your search.</div>'
      : '<div class="empty">'+EMPTY_MSG[view]+'</div>';
    renderFilterTags(); return;
  }
  el.innerHTML="";
  shown.forEach(it=>{
    const d=domainOf(it.url);
    const div=document.createElement("div"); div.className="item";
    const laterBadge = (it.later && !it.archived && view!=="later") ? '<span class="laterbadge">Read later</span>' : '';
    div.innerHTML =
      '<div class="fav">'+(d.charAt(0).toUpperCase()||"?")+'</div>'+
      '<div style="flex:1"><div class="t">'+esc(it.title)+laterBadge+'</div>'+
      '<div class="u">'+esc(it.url)+'</div>'+
      (it.note?'<div class="note">'+esc(it.note)+'</div>':'')+
      (it.tags.length?'<div class="tags">'+it.tags.map(t=>'<span class="tag">'+esc(t)+'</span>').join('')+'</div>':'')+
      '<div class="actions"></div>'+
      '</div>';
    const acts=div.querySelector(".actions");
    if(it.archived){
      acts.appendChild(mkBtn("Restore to All", ()=>{ it.archived=false; refresh(); }));
    } else {
      const lb=mkBtn(it.later?"★ In read later":"☆ Read later", ()=>{ it.later=!it.later; refresh(); });
      if(it.later) lb.classList.add("on");
      acts.appendChild(lb);
      acts.appendChild(mkBtn("Archive", ()=>{ it.archived=true; refresh(); }));
    }
    el.appendChild(div);
  });
}
function mkBtn(label, fn){ const b=document.createElement("button"); b.textContent=label; b.onclick=fn; return b; }
function refresh(){ renderNav(); renderFilterTags(); renderItems(); }

document.querySelectorAll(".navbtn").forEach(b=>{
  b.onclick=()=>{ view=b.dataset.view; activeTag=null; $("search").value=""; refresh(); };
});

