function doFetch(){
  const u = $("url").value.trim();
  if(!u){ toast("Paste a link first"); return; }
  if(!domainOf(u)){ toast("That doesn't look like a valid link"); return; }
  // simulate a link whose details cannot be retrieved automatically
  const failed = u.includes("no-details");
  const meta = failed ? {title:"", desc:""} : lookup(u);
  pending = { url:u, title:meta.title, desc:meta.desc, tags:[] };
  $("pvFav").textContent = domainOf(u).charAt(0).toUpperCase() || "?";
  if(failed){
    $("pvTitle").textContent = "Couldn't fetch details automatically";
    $("pvDesc").textContent = "You can still add a title and save this link.";
    $("titleEdit").value = "";
    $("titleEdit").placeholder = "Type a title for this link";
  } else {
    $("pvTitle").textContent = meta.title;
    $("pvDesc").textContent = meta.desc;
    $("titleEdit").value = meta.title;
  }
  $("note").value = "";
  $("tagInput").value = "";
  renderTags();
  $("preview").style.display = "block";
}

