input[type=text], input[type=url], textarea {
  width:100%; padding:10px 12px; border:1px solid var(--line); border-radius:8px;
  font-size:15px; font-family:inherit; color:var(--ink); background:#fff;
}
textarea { resize:vertical; min-height:52px; }
.hint { font-size:12px; color:var(--muted); margin:6px 0 0; }

.inline { display:flex; gap:10px; align-items:center; flex-wrap:wrap; }
.inline input { flex:1; min-width:0; }
.actions { margin-top:16px; }

.btn { border:0; border-radius:8px; padding:10px 16px; font-size:15px; cursor:pointer; }
.btn.primary { background:var(--accent); color:var(--accent-ink); }
.btn.ghost { background:#eef1f5; color:var(--ink); }
.btn.small { font-size:13px; padding:6px 11px; background:#eef1f5; color:var(--ink); }
.btn.small.on { background:var(--later-bg); color:var(--later-ink); }

.editor { margin-top:14px; }
.banner { background:var(--later-bg); color:var(--later-ink); border-radius:8px; padding:9px 12px; font-size:13px; margin-bottom:10px; }
.dup { margin-top:14px; padding:12px; background:var(--later-bg); border:1px solid #f0d98a; border-radius:10px; }
.dup p { margin:0 0 10px; }

.chips { display:flex; flex-wrap:wrap; gap:6px; margin-top:8px; }
.chip {
  background:#eef1f5; border-radius:999px; padding:4px 10px; font-size:13px;
  display:inline-flex; align-items:center; gap:6px;
}
.chip .x { background:none; border:0; padding:0; color:var(--muted); font-size:15px; line-height:1; cursor:pointer; }
.chips.filter .chip { cursor:pointer; }
.chips.filter .chip.active { background:var(--accent); color:var(--accent-ink); }

.listheading { font-size:13px; color:var(--muted); text-transform:uppercase; letter-spacing:.05em; margin:0 0 12px; }

.item { display:flex; gap:12px; padding:14px 0; border-bottom:1px solid var(--line); }
.item:last-child { border-bottom:0; }
.item .fav {
  width:32px; height:32px; border-radius:8px; background:#dbe4f3; color:var(--accent);
  display:flex; align-items:center; justify-content:center; font-weight:700; flex:0 0 auto;
}
.item .body { flex:1; min-width:0; }
.item .title { font-weight:600; }
.item .title a { color:inherit; text-decoration:none; }
.item .title a:hover { text-decoration:underline; }
.badge { font-size:12px; color:var(--later-ink); background:var(--later-bg); border-radius:999px; padding:2px 8px; margin-left:8px; white-space:nowrap; }
.item .url { font-size:12px; color:var(--muted); word-break:break-all; margin-top:2px; }
.item .note { font-size:14px; margin-top:5px; white-space:pre-wrap; word-break:break-word; }
.item .itemtags { margin-top:7px; }
.item .itemactions { display:flex; flex-wrap:wrap; gap:8px; margin-top:9px; }

.empty { color:var(--muted); text-align:center; padding:28px 12px; }

.toast {
  position:fixed; left:50%; bottom:24px; transform:translateX(-50%);
  background:var(--ink); color:#fff; padding:10px 18px; border-radius:999px;
  font-size:14px; opacity:0; transition:opacity .2s; pointer-events:none; z-index:10;
}
.toast.show { opacity:1; }

@media (max-width:520px){
  .inline { flex-direction:column; align-items:stretch; }
  .inline .btn { width:100%; }
  main, .tabs { padding-left:12px; padding-right:12px; }
}

