    el.innerHTML = '<div class="empty">' +
      (filtering ? "No bookmarks match your search." : EMPTY_MSG[view]) + "</div>";
    return;
  }
  el.innerHTML = "";
  items.forEach((it) => el.appendChild(renderItem(it)));
}

function renderItem(it) {
  const d = domainOf(it.url);
